from pathlib import Path
import json,subprocess,re,hashlib
from PIL import Image,ImageDraw
import imageio_ffmpeg
ROOT=Path('D:/BOF-Downloads/2026-11-14/RevG-source');OUT=ROOT/'_shots/hq_turns_1115';FF=imageio_ffmpeg.get_ffmpeg_exe()
q=json.loads((OUT/'recording.json').read_text(encoding='utf8'));assert q['coreBefore']==q['coreAfter']and not q['errors'];c=q['clips'][0];assert len(q['clips'])==1 and not c['errors']
def run(args):
 p=subprocess.run([FF,'-hide_banner','-loglevel','error','-y',*args],capture_output=True,text=True);assert p.returncode==0 and not p.stderr,p.stderr
def duration(path):
 p=subprocess.run([FF,'-hide_banner','-i',str(path)],capture_output=True,text=True);m=re.search(r'Duration: (\d+):(\d+):([\d.]+)',p.stderr);return int(m[1])*3600+int(m[2])*60+float(m[3])
def event(s):return next(x['at']for x in c['stages']if s in x['tag'])
encoded=OUT/'fast-turns-encoded.mp4';run(['-i',str(OUT/'films/hq5.webm'),'-vf','fps=30','-fps_mode','cfr','-c:v','libx264','-preset','fast','-crf','21','-pix_fmt','yuv420p','-threads','2','-af','aresample=async=1:first_pts=0','-c:a','aac','-b:a','160k',str(encoded)])
total=duration(encoded)
chapters=[{'start':0,'title':'Faster individual banked departures'},{'start':6.3,'title':'Juggernaut frame-by-frame turn'},{'start':event(':HQ19-QUIET:'),'title':'Five quiet seconds'},{'start':event(':HQ19-ATTACK:'),'title':'Attack on Fury HQ'},{'start':event(':HQ19-DECKER:'),'title':'Decker and Axel counterattack'},{'start':event(':HQ19-DECKER:')+8.8,'title':'Decker fast southeast turn'},{'start':event(':HQ19-AXEL:')+.7,'title':'Axel fast southwest turn'},{'start':event('intro:'),'title':'Native Stage 6 handoff'}]
meta=';FFMETADATA1\ntitle=BOF - Faster frame-by-frame HQ turns\n'
for i,ch in enumerate(chapters):meta+='[CHAPTER]\nTIMEBASE=1/1000\nSTART='+str(round(ch['start']*1000))+'\nEND='+str(round((chapters[i+1]['start']if i+1<len(chapters)else total)*1000))+'\ntitle='+ch['title']+'\n'
(OUT/'chapters.ffmeta').write_text(meta,encoding='utf8');movie=OUT/'hq-turns-fast.mp4';run(['-i',str(encoded),'-f','ffmetadata','-i',str(OUT/'chapters.ffmeta'),'-map','0:v:0','-map','0:a:0','-map_metadata','1','-map_chapters','1','-c','copy','-movflags','+faststart',str(movie)]);run(['-i',str(movie),'-f','null','-'])
p=subprocess.run([FF,'-hide_banner','-i',str(movie),'-af','volumedetect','-vn','-f','null','-'],capture_output=True,text=True);audio=[x.strip()for x in p.stderr.splitlines()if'mean_volume:'in x or'max_volume:'in x];assert len(audio)==2 and not any('-inf'in x for x in audio)
points=[(2.35,'Cole banked turn'),(6.85,'Juggernaut banked turn'),(event(':HQ19-DECKER:')+9.35,'Decker fast exit'),(event(':HQ19-AXEL:')+1.25,'Axel fast exit')];contact=Image.new('RGB',(1280,768),'#102030');d=ImageDraw.Draw(contact)
for i,(t,title)in enumerate(points):
 path=OUT/('frame-'+str(i)+'.png');run(['-ss',str(t),'-i',str(movie),'-frames:v','1',str(path)]);im=Image.open(path).convert('RGB');im.thumbnail((640,360));x=i%2*640;y=i//2*384;contact.paste(im,(x,y));d.text((x+10,y+362),title,fill='white')
contact.save(OUT/'contact-sheet.jpg',quality=94)
q['combined']={'file':movie.name,'duration':duration(movie),'chapters':chapters,'decodeErrors':[],'sha256':hashlib.sha256(movie.read_bytes()).hexdigest(),'audio':audio};(OUT/'recording.json').write_text(json.dumps(q,indent=2),encoding='utf8')
buttons=''.join('<button data-time="'+str(ch['start'])+'">'+ch['title']+'</button>'for ch in chapters)
gifs=''.join('<figure><figcaption>'+pk.title()+'</figcaption><img src="'+pk+'-turn.gif" alt="'+pk+' actual banking frames"></figure>'for pk in ['cole','maverick','freezer','juggernaut','yuri','lizzie','falva','decker','axel'])
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOF - Faster frame-by-frame HQ turns</title><style>body{max-width:1200px;margin:25px auto;padding:0 20px;background:#0c1723;color:#f1e9d7;font:17px/1.6 system-ui}video,.contact{width:100%}button{padding:9px;margin:4px;background:#253d51;color:#fff;border:1px solid #668ba5;border-radius:4px;cursor:pointer}a{color:#8fe3d0}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px}.gallery img{width:100%}figure{margin:0}small{color:#a9bfd0}</style><h1>Faster frame-by-frame HQ turns</h1><p>Twenty fixed-pivot banking/exhaust frames per actual pilot aircraft. Fly-outs now take1.3 seconds each, with alternating southwest/southeast routes and one ship departing at a time.</p><video id="movie" controls preload="metadata" poster="frame-1.png" src="hq-turns-fast.mp4"></video><p>__BUTTONS__</p><p><small>Cole / Hard, native game audio. Focused prepared cinematic checkpoint from the squad launch through the five-second pause, base attack, six guard takedowns and individual escapes into the native Stage6 opening. Earlier homecoming omitted. Not a full campaign playthrough.</small></p><p><a href="../../docs/HQ_TURNS_1115.md">Changes and verification</a></p><details><summary>All nine aircraft turn-frame previews</summary><div class="gallery">__GIFS__</div></details><img class="contact" src="contact-sheet.jpg" alt="Recorded fast banked departures"><script>const v=document.getElementById('movie');document.querySelectorAll('button').forEach(b=>b.onclick=async()=>{v.currentTime=Number(b.dataset.time);try{await v.play()}catch(e){if(e.name!=='AbortError')throw e}});</script></html>'''
(OUT/'review.html').write_text(html.replace('__BUTTONS__',buttons).replace('__GIFS__',gifs),encoding='utf8');print(json.dumps(q['combined'],indent=2),flush=True)
